package com.cpgame.batchd.treasurehunt.api;

import com.cpgame.batchd.treasurehunt.core.GameRuleCore;import com.fasterxml.jackson.databind.ObjectMapper;import com.sun.net.httpserver.HttpExchange;import com.sun.net.httpserver.HttpServer;import java.io.ByteArrayOutputStream;import java.io.InputStream;import java.math.BigDecimal;import java.net.InetSocketAddress;import java.net.URLDecoder;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.nio.file.Path;import java.security.SecureRandom;import java.time.Instant;import java.time.ZoneOffset;import java.time.format.DateTimeFormatter;import java.util.ArrayList;import java.util.LinkedHashMap;import java.util.List;import java.util.Map;import java.util.concurrent.Executors;

public final class DemoServer{private final ObjectMapper json=new ObjectMapper();private final ServerConfig config;private final CacheRepository cache;private final StateStore state;private final SecureRandom random=new SecureRandom();private DemoServer(ServerConfig c)throws Exception{config=c;cache=new CacheRepository(c);state=new StateStore(c.stateFile(),json);}
    public static void main(String[]args)throws Exception{Path conf=null,publish=null;int port=0;for(int i=0;i<args.length;i++){if("--config".equals(args[i]))conf=Path.of(args[++i]);else if("--port".equals(args[i]))port=Integer.parseInt(args[++i]);else if("--publish".equals(args[i]))publish=Path.of(args[++i]);}if(conf==null)throw new IllegalArgumentException("--config required");if(port==0){String env=System.getenv("PORT");port=env==null?51810:Integer.parseInt(env);}var app=new DemoServer(ServerConfig.load(conf,publish));HttpServer server=HttpServer.create(new InetSocketAddress("0.0.0.0",port),0);server.createContext("/",app::handle);server.setExecutor(Executors.newCachedThreadPool());server.start();System.out.printf("READY http://127.0.0.1:%d/?gid=1810&token=local-1810&language=en&sip=127.0.0.1%%3A%d rulesHash=%s%n",port,port,GameRuleCore.RULES_HASH);}
    private void handle(HttpExchange x){try{String path=x.getRequestURI().getPath();if("OPTIONS".equals(x.getRequestMethod())){cors(x);x.sendResponseHeaders(204,-1);return;}if(path.equals("/health")||path.equals("/api/health")){sendJson(x,200,Map.of("status","UP","gameId",1810,"rulesHash",GameRuleCore.RULES_HASH,"redisDatabase",15));return;}if(path.endsWith("/config/initialData")){sendJson(x,200,envelope(initialConfig()));return;}if(path.endsWith("/single_game.Game/initRoom")){sendJson(x,200,envelope(initial()));return;}if(path.endsWith("/activity/getActivity")){sendJson(x,200,envelope(Map.of("free",Map.of("act_list",List.of(),"invite_act_have",0,"invite_end_time",0))));return;}if(path.endsWith("/account/getUserInfo")){var s=state.snapshot();sendJson(x,200,envelope(Map.of("currency","R$","gid",1810,"gold",s.balance())));return;}if(path.equals("/api/spin")||path.endsWith("/single_game.Game/gameResult")){sendJson(x,200,envelope(spin(params(x),null)));return;}if(path.equals("/api/test/select")){Map<String,String>p=params(x);sendJson(x,200,envelope(spin(p,p.getOrDefault("mode","loss"))));return;}if(path.endsWith("/goldgame/single_game_user_gold_history")){sendJson(x,200,envelope(days()));return;}if(path.endsWith("/goldgame/single_game_user_history")){sendJson(x,200,envelope(history(params(x))));return;}if(path.equals("/api/history")){sendJson(x,200,state.snapshot().history());return;}if(path.equals("/history")){send(x,200,"text/html; charset=utf-8",historyPage().getBytes(StandardCharsets.UTF_8));return;}serveStatic(x,path);}catch(Exception e){try{sendJson(x,500,Map.of("code",500,"msg",e.getMessage()==null?e.getClass().getSimpleName():e.getMessage(),"data",Map.of()));}catch(Exception ignored){}}finally{x.close();}}
    private Map<String,Object>initialConfig(){Map<String,Object>game=new LinkedHashMap<>();game.put("bet_gold",List.of(0.05,0.5,4));game.put("buy_free_max_bet",-1);game.put("default_bet_gold",0);game.put("default_level",10);game.put("game_way",List.of(Map.of("max_bet_gold","0.00","min_bet_gold","0.00","way_id",181010000,"win_multi","1.00")));game.put("gid",1810);game.put("least_gold",0);game.put("name","Magic Scroll");game.put("status","1");Map<String,Object>servers=new LinkedHashMap<>();for(String k:List.of("gos_host","gos_sport","gs_host","gs_host1","gs_port","gs_port1","gs_push_host","gs_push_port","gs_sport","gs_sport1","ps_host","ps_port","snake_gs_host","snake_gs_port","snake_gs_sport","snake_gs_url"))servers.put(k,"");servers.put("gos_port","8976");servers.put("gs_push_sport","28966");servers.put("ngs_switch",0);Map<String,Object>d=new LinkedHashMap<>();d.put("game_address",Map.of("ship_address_config",Map.of()));d.put("game_info",game);d.put("game_server",servers);d.put("initial_config",Map.of("bd_bet_count",2,"current_sys_time",Instant.now().getEpochSecond(),"is_debug",false,"is_stopgs",0,"user_on_hook_time",600,"version",1745909504));d.put("language","en-us");d.put("r",1);d.put("zone",0);return d;}
    private Map<String,Object>initial(){var s=state.snapshot();int[]board=new int[10];for(int i=0;i<10;i++)board[i]=1+random.nextInt(6);Map<String,Object>game=Map.of("bet_gold",List.of(0.05,0.5,4),"buy_free_max_bet",-1,"default_bet_gold",0,"default_level",10,"game_way",Map.of("max",0,"min",0,"way_id",181010000,"win_multi",1),"gid",1810,"least_gold",0,"name","Treasure Hunt","status",1);Map<String,Object>user=Map.of("currency","R$","gid",1810,"gold",s.balance());Map<String,Object>d=new LinkedHashMap<>();d.put("bet",0.05);d.put("bet_gold",5);d.put("change_gold",0);d.put("end_gold",s.balance());d.put("level",10);d.put("odds",0);d.put("oid","init-1810");d.put("prop_odds",paytable());d.put("props",List.of(Map.of("all",0,"prop",ProviderPresenter.ints(board),"tw",0,"win_arr",List.of())));d.put("small_game_type",0);d.put("start_gold",s.balance());d.put("total_win",0);d.put("type",1);d.put("game_info",game);d.put("initial_config",Map.of("bd_bet_count",2,"is_debug",false,"is_stopgs",0,"user_on_hook_time",600,"version",1745909504));d.put("language","en-us");d.put("user_info",user);d.put("user_config",null);d.put("zone",0);return d;}
    private Map<String,Object>spin(Map<String,String>p,String forced)throws Exception{BigDecimal bet=new BigDecimal(p.getOrDefault("bet_gold","0.05"));int level=Integer.parseInt(p.getOrDefault("level","10"));CacheRepository.Pool pool;if(forced!=null)pool=switch(forced.toLowerCase()){case"win"->CacheRepository.Pool.ORDINARY_WIN;case"treasure","treasure_hunt"->CacheRepository.Pool.TREASURE_HUNT;case"all","all_reels_multiplier"->CacheRepository.Pool.ALL_REELS_MULTIPLIER;default->CacheRepository.Pool.ORDINARY_LOSS;};else if(random.nextDouble()<config.specialProbability())pool=random.nextDouble()<config.treasureRatio()?CacheRepository.Pool.TREASURE_HUNT:CacheRepository.Pool.ALL_REELS_MULTIPLIER;else pool=random.nextDouble()<config.ordinaryLossProbability()?CacheRepository.Pool.ORDINARY_LOSS:CacheRepository.Pool.ORDINARY_WIN;var round=cache.take(pool);var prepared=ProviderPresenter.prepare(round,bet,level);var applied=state.apply(prepared.betCost(),prepared.totalWin(),prepared.detail());return ProviderPresenter.finish(prepared,applied);}
    private Map<String,Object>days(){List<Map<String,Object>>h=state.snapshot().history();long today=Instant.now().getEpochSecond()/86400*86400;List<Map<String,Object>>list=new ArrayList<>();BigDecimal totalBet=BigDecimal.ZERO,totalChange=BigDecimal.ZERO;for(int offset=0;offset<7;offset++){long day=today-offset*86400L;BigDecimal bet=BigDecimal.ZERO,change=BigDecimal.ZERO;for(var e:h){long time=((Number)e.get("time")).longValue(),rowDay=time-time%86400;if(rowDay==day){bet=bet.add(new BigDecimal(String.valueOf(e.get("bet_gold"))));change=change.add(new BigDecimal(String.valueOf(e.get("change_gold"))));}}list.add(Map.of("day",day,"bet_gold",bet,"change_gold",change));totalBet=totalBet.add(bet);totalChange=totalChange.add(change);}return Map.of("list",list,"statistics",Map.of("total_bet_gold",totalBet,"total_change_gold",totalChange));}
    private Map<String,Object>history(Map<String,String>p){List<Map<String,Object>>all=state.snapshot().history();String requested=p.getOrDefault("day","");List<Map<String,Object>>filtered=all.stream().filter(e->{if(requested.isBlank())return true;long time=((Number)e.get("time")).longValue(),day=time-time%86400;return requested.equals(Long.toString(day));}).toList();int size=Math.max(1,Integer.parseInt(p.getOrDefault("page_size","20"))),page=Math.max(1,Integer.parseInt(p.getOrDefault("page","1"))),from=Math.min(filtered.size(),(page-1)*size),to=Math.min(filtered.size(),from+size);BigDecimal totalBet=filtered.stream().map(e->new BigDecimal(String.valueOf(e.get("bet_gold")))).reduce(BigDecimal.ZERO,BigDecimal::add),totalChange=filtered.stream().map(e->new BigDecimal(String.valueOf(e.get("change_gold")))).reduce(BigDecimal.ZERO,BigDecimal::add);return Map.of("list",filtered.subList(from,to),"statistics",Map.of("total_bet_gold",totalBet,"total_change_gold",totalChange));}
    private Map<String,Object>paytable(){Map<String,Object>m=new LinkedHashMap<>();GameRuleCore.PAYTABLE.forEach((k,v)->m.put(String.valueOf(k),v));return m;}private Map<String,Object>envelope(Object data){return Map.of("code",0,"data",data,"msg","success","time",Instant.now().getEpochSecond());}
    private Map<String,String>params(HttpExchange x)throws Exception{String raw=x.getRequestURI().getRawQuery();if("POST".equalsIgnoreCase(x.getRequestMethod()))raw=(raw==null?"":raw+"&")+new String(x.getRequestBody().readAllBytes(),StandardCharsets.UTF_8);Map<String,String>m=new LinkedHashMap<>();if(raw!=null)for(String pair:raw.split("&")){int at=pair.indexOf('=');if(at>=0)m.put(URLDecoder.decode(pair.substring(0,at),StandardCharsets.UTF_8),URLDecoder.decode(pair.substring(at+1),StandardCharsets.UTF_8));}return m;}
    private void serveStatic(HttpExchange x,String raw)throws Exception{String rel=raw.equals("/")?"index.html":raw.substring(1);Path file=config.publishDirectory().resolve(rel).normalize();if(!Files.isRegularFile(file)){String alias=switch(file.getFileName().toString()){case"0a656266-bd72-44b2-87d0-286a1c048f7e.189e7.mp3"->"assets/Game1810/native/77/778bde35-92f4-4765-b352-fe245d6ec584.a94b7.mp3";case"461f1be3-a046-42ce-8f77-6cf0d5ca9521.af8f0.mp3"->"assets/Game1810/native/2e/2ec83190-f187-41c8-9113-5a3d495dd5b8.3f2a6.mp3";case"a3641f36-22cc-4daf-a400-94285e9fd779.abeb0.mp3"->"assets/Game1810/native/11/1128a809-723c-47ea-ac1b-25cefe39b261.c3f38.mp3";default->rel.startsWith("assets/Game1810/native/")&&rel.endsWith(".mp3")?"assets/Game1810/native/77/778bde35-92f4-4765-b352-fe245d6ec584.a94b7.mp3":null;};if(alias!=null)file=config.publishDirectory().resolve(alias).normalize();}if(!file.startsWith(config.publishDirectory())||!Files.isRegularFile(file)){send(x,404,"text/plain",("not found: "+raw).getBytes(StandardCharsets.UTF_8));return;}send(x,200,mime(file),Files.readAllBytes(file));}
    private String historyPage(){return "<!doctype html><meta charset=utf-8><title>Treasure Hunt History</title><style>body{font:15px system-ui;background:#10233a;color:#eef;padding:24px}table{border-collapse:collapse;width:100%}td,th{padding:8px;border-bottom:1px solid #456}</style><h1>Treasure Hunt History</h1><table><thead><tr><th>Round</th><th>Mode</th><th>Bet</th><th>Win</th><th>Change</th></tr></thead><tbody id=t></tbody></table><script>fetch('/api/history').then(r=>r.json()).then(a=>t.innerHTML=a.map(x=>`<tr><td>${x.oid}</td><td>${x.extend.mode}</td><td>${x.bet_gold}</td><td>${x.total_win}</td><td>${x.change_gold}</td></tr>`).join(''))</script>";}
    private static String mime(Path p){String n=p.getFileName().toString().toLowerCase();if(n.endsWith(".html"))return"text/html; charset=utf-8";if(n.endsWith(".js"))return"application/javascript";if(n.endsWith(".json"))return"application/json";if(n.endsWith(".css"))return"text/css";if(n.endsWith(".png"))return"image/png";if(n.endsWith(".jpg")||n.endsWith(".jpeg"))return"image/jpeg";if(n.endsWith(".mp3"))return"audio/mpeg";return"application/octet-stream";}
    private void sendJson(HttpExchange x,int code,Object body)throws Exception{send(x,code,"application/json; charset=utf-8",json.writeValueAsBytes(body));}private void send(HttpExchange x,int code,String type,byte[]body)throws Exception{cors(x);x.getResponseHeaders().set("Content-Type",type);x.getResponseHeaders().set("Cache-Control","no-store");x.sendResponseHeaders(code,body.length);x.getResponseBody().write(body);}private void cors(HttpExchange x){x.getResponseHeaders().set("Access-Control-Allow-Origin","*");x.getResponseHeaders().set("Access-Control-Allow-Headers","Content-Type");x.getResponseHeaders().set("Access-Control-Allow-Methods","GET,POST,OPTIONS");}
}
